const AT='2026-10-12T12:00:00.000Z';
function fixture(){
 const sqlite=new DatabaseSync(':memory:');sqlite.exec('PRAGMA foreign_keys=ON;');
 for(const sql of [...DOMAIN_SCHEMA,...ANALYSIS_SCHEMA,...COACH_SCHEMA,...TEAM_FEATURE_SCHEMA,...DATA_FILE_SCHEMA,...SYNC_SCHEMA,...SECURITY_SCHEMA])sqlite.exec(sql);
 const insert=(table,row)=>sqlite.prepare(`INSERT INTO ${table}(${Object.keys(row)}) VALUES(${Object.keys(row).map(()=>'?')})`).run(...Object.values(row));
 const db={prepare(sql){const stmt={sql,params:[],bind(...params){return {...stmt,params};},async first(column){const row=sqlite.prepare(sql).get(...this.params);return column?row?.[column]??null:row?{...row}:null;},async all(){return {results:sqlite.prepare(sql).all(...this.params).map(r=>({...r}))};},async run(){const r=sqlite.prepare(sql).run(...this.params);return {meta:{changes:Number(r.changes)}};}};return stmt;},async batch(statements){sqlite.exec('BEGIN');try{const result=[];for(const s of statements)result.push(await s.run());sqlite.exec('COMMIT');return result;}catch(e){sqlite.exec('ROLLBACK');throw e;}}};
 insert('domain_installation',{id:1,schema_version:1,created_at:AT});
 const repo=new DomainRepository(db),commit=page=>{sqlite.exec('BEGIN');try{for(const s of page.statements)sqlite.prepare(s.sql.replaceAll('$FENCE','1')).run(...s.params.map(v=>v instanceof ArrayBuffer?new Uint8Array(v):v));sqlite.exec('COMMIT');}catch(e){sqlite.exec('ROLLBACK');throw e;}};
 const source=(native='1',provider='gotsport',account=null)=>{const id=sourceKey(provider,native,account);insert('source_teams',{id,provider,scope:account||'public',account_id:account,native_id:native,name:'Team '+native,name_authority:3,archived:0,evidence:'{}',content_hash:'source-'+native,observed_at:AT});return id;};
 const team=(id,root,{mode='observed_history',account=null}={})=>{insert('app_teams',{id,name:id,timezone:'UTC',season_year:0,created_at:AT});insert('team_read_state',{app_team_id:id});insert('team_source_connections',{id:'root-'+id,app_team_id:id,source_team_id:root,account_id:account,scope_mode:mode,created_at:AT});};
 const season=(team,year)=>{const id=team+'-'+year;insert('team_seasons',{id,app_team_id:team,year,start_day:`${year}-06-01`,end_day:`${year+1}-06-01`,start_at:`${year}-06-01T00:00:00.000Z`,end_at:`${year+1}-06-01T00:00:00.000Z`});return id;};
 const event=async(native,root,day=null,{provider='gotsport',accountId=null,generation=null,...other}={})=>commit(await repo.buildSourcePage({accountId,generation,fixtures:[{provider,native_id:native,id:provider+':'+native,home_id:provider+':'+root.split('/').at(-1),local_day:day,type:'game',status:'FINAL',payload:'{}',observed_at:AT,...other}]}));
 const archive=async team=>{const descriptor=await sourceDatasetSections(repo,team);const segments=[];for(const section of descriptor.sections){const all=(await db.prepare(section.sql).bind(...section.params).all()).results;for(let n=0;n<all.length;n+=10)segments.push({section:section.key,rows:encodeDatasetRows(repo,section.key,all.slice(n,n+10))});}return {descriptor,segments};};
 return {sqlite,db,insert,repo,commit,source,team,season,event,archive,close:()=>sqlite.close()};
}
test('logical team export includes every observed season and pending events without selected season',async()=>{const f=fixture();try{const root=f.source();f.team('team',root);await f.event('old',root,'2024-08-04');await f.event('recent',root,'2026-08-04');await f.event('pending',root);const {descriptor,segments}=await f.archive('team');assert.equal(descriptor.scope.scope_kind,'connected_history');assert.equal(descriptor.scope.season_year,undefined);assert.deepEqual(segments.filter(s=>s.section==='source_events@public').flatMap(s=>s.rows.map(r=>r.native_id)).sort(),['old','pending','recent']);assert.equal(f.sqlite.prepare('SELECT COUNT(*) n FROM team_seasons').get().n,0);}finally{f.close();}});
test('fixed roots and explicit exclusions constrain saved history and snapshot signatures',async()=>{const f=fixture();try{const root=f.source();f.team('team',root);const excluded=f.season('team',2024);f.insert('team_connection_seasons',{connection_id:'root-team',team_season_id:excluded,basis:'events',excluded:1});await f.event('old',root,'2024-08-04');await f.event('recent',root,'2026-08-04');await f.event('pending',root);let data=await f.archive('team');assert.deepEqual(data.segments.filter(s=>s.section==='source_events@public').flatMap(s=>s.rows.map(r=>r.native_id)).sort(),['pending','recent']);const q=datasetRevisionQuery('team',null),before=await f.db.prepare(q.sql).bind(...q.params).first('signature');f.sqlite.prepare("UPDATE team_source_connections SET scope_mode='fixed_seasons' WHERE id='root-team'").run();data=await f.archive('team');assert.deepEqual(data.segments.filter(s=>s.section==='source_events@public').flatMap(s=>s.rows.map(r=>r.native_id)),['pending']);assert.notEqual(await f.db.prepare(q.sql).bind(...q.params).first('signature'),before);}finally{f.close();}});

import {DataFileService} from '../src/reporting/data-files.js';
import {VERSION} from '../src/application/version.js';
const hash=async text=>Buffer.from(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text))).toString('hex');
async function manifestFor(archive){return {format:'myts-source-dataset',format_version:'7.2',release:VERSION,scope:archive.descriptor.scope,segments:await Promise.all(archive.segments.map(async(s,i)=>({ordinal:i,name:'segments/'+String(i).padStart(6,'0')+'.json',section:s.section,row_count:s.rows.length,sha256:await hash(JSON.stringify(s))})))};}
const service=f=>new DataFileService(f.db,{coordinator:{enqueue:async()=> 'queued'},now:()=>Date.parse(AT)});
async function stage(f,archive){const svc=service(f),manifest=await manifestFor(archive),started=await svc.startImport({team_id:'target',manifest});for(const [i,payload]of archive.segments.entries())await svc.uploadSegment(started.id,i,payload);await svc.commitImport(started.id);return {svc,id:started.id,manifest};}
async function finish(f,svc,id){for(let n=0;n<150;n++){const page=await svc.apply(id);f.commit(page);if(page.complete)return svc.importStatus(id);}throw new Error('Import did not finish.');}
test('an authorized zero-season team restores a missing staged graph without provider collection',async()=>{const source=fixture(),target=fixture();try{let root=source.source();const opponent=source.source('2');source.team('original',root);await source.event('old',root,'2024-08-04',{away_id:'gotsport:2'});await source.event('recent',root,'2026-08-04');await source.event('pending',root);const archive=await source.archive('original');root=target.source();target.team('target',root);const {svc,id}=await stage(target,archive);assert.equal(target.sqlite.prepare('SELECT COUNT(*) n FROM source_events').get().n,0);let status=await svc.importStatus(id);assert.equal(status.state,'queued');while(['queued','validating'].includes(status.state)){target.commit(await svc.apply(id));assert.equal(target.sqlite.prepare('SELECT COUNT(*) n FROM source_events').get().n,0,'validation writes no native observations');status=await svc.importStatus(id);}await finish(target,svc,id);assert.equal(target.sqlite.prepare('SELECT COUNT(*) n FROM source_events').get().n,3);assert.equal(target.sqlite.prepare('SELECT COUNT(*) n FROM source_teams').get().n,2);assert.equal(target.sqlite.prepare('SELECT COUNT(*) n FROM provider_accounts').get().n,0);assert.equal(target.sqlite.prepare('SELECT COUNT(*) n FROM source_team_links').get().n,0);assert.equal(target.sqlite.prepare("SELECT COUNT(*) n FROM source_events WHERE provenance='file_import'").get().n,3);assert.equal((await svc.list({team_id:'target',type:'imports'})).items[0].id,id);}finally{source.close();target.close();}});
test('a bad late graph segment is rejected before any source observation is applied',async()=>{const source=fixture(),target=fixture();try{const root=source.source();source.team('original',root);await source.event('good',root,'2024-08-04');const archive=await source.archive('original'),foreign={...archive.segments.find(s=>s.section==='source_events@public').rows[0],id:'gotsport/public/foreign',native_id:'foreign',home_source_team_id:'gotsport/public/evil'};archive.segments.push({section:'source_events@public',rows:[foreign]});const targetRoot=target.source();target.team('target',targetRoot);const {svc,id}=await stage(target,archive);await assert.rejects(()=>finish(target,svc,id),e=>e.code==='data_scope_invalid');assert.equal(target.sqlite.prepare('SELECT COUNT(*) n FROM source_events').get().n,0);}finally{source.close();target.close();}});

test('period-qualified historical roster snapshots keep names and jerseys without creating source authority',async()=>{const source=fixture(),target=fixture();try{const account={id:'account-source',provider:'teamsnap',native_id:'native-account',name:'Owner'};source.insert('provider_accounts',account);const root=source.source('team1','teamsnap',account.id);source.team('original',root,{account:account.id});const season=source.season('original',2024),player=sourceKey('teamsnap','player1',account.id);source.insert('source_players',{id:player,provider:'teamsnap',scope:account.id,account_id:account.id,native_id:'player1',name:'Current name',jersey:'22',evidence:'{}',content_hash:'player',observed_at:AT});source.insert('team_connection_seasons',{connection_id:'root-original',team_season_id:season,basis:'imported_snapshot'});source.insert('connection_roster_evidence',{connection_id:'root-original',team_season_id:season,source_player_id:player,basis_key:'accepted',basis:'accepted_projection',certainty:'preserved_uncertain',name:'Historical name',jersey:'8',observed_at:AT,source_hash:'old'});const archive=await source.archive('original');assert.equal(archive.segments.find(s=>s.section==='source_roster_snapshots@account1').rows[0].jersey,'8');target.insert('provider_accounts',{...account,id:'account-target'});const tr=target.source('team1','teamsnap','account-target');target.team('target',tr,{account:'account-target'});const {svc,id}=await stage(target,archive);await finish(target,svc,id);const snapshot=target.sqlite.prepare('SELECT * FROM connection_roster_evidence').get();assert.equal(snapshot.basis,'imported_snapshot');assert.equal(snapshot.certainty,'preserved_uncertain');assert.equal(snapshot.name,'Historical name');assert.equal(snapshot.jersey,'8');assert.equal(target.sqlite.prepare('SELECT year FROM team_seasons').get().year,2024);assert.equal(target.sqlite.prepare('SELECT COUNT(*) n FROM account_source_teams').get().n,0);assert.equal(target.sqlite.prepare('SELECT COUNT(*) n FROM connection_event_resolutions').get().n,0);assert.equal(target.sqlite.prepare('SELECT COUNT(*) n FROM source_attendance').get().n,0);const again=await stage(target,archive);await finish(target,again.svc,again.id);assert.equal(target.sqlite.prepare('SELECT COUNT(*) n FROM connection_roster_evidence').get().n,1,'replay retains one imported audit observation');}finally{source.close();target.close();}});
test('competition-only history restores missing competitions, divisions and registrations',async()=>{const source=fixture(),target=fixture();try{const root=source.source();source.team('original',root);source.commit(await source.repo.buildSourcePage({records:{competitions:[{provider:'gotsport',id:'gotsport:cup',native_id:'cup',name:'Cup',kind:'tournament',starts_on:'2024-10-01',ends_on:'2024-10-03',details:'{}',observed_at:AT}],divisions:[{id:'gotsport:division',competition_id:'gotsport:cup',name:'Premier',details:'{}',observed_at:AT}],memberships:[{team_id:'gotsport:1',division_id:'gotsport:division',registration_id:'registration1',evidence:'{}',observed_at:AT}]}}));const archive=await source.archive('original');assert.ok(archive.segments.some(s=>s.section==='source_competitions@public'));const targetRoot=target.source();target.team('target',targetRoot);const {svc,id}=await stage(target,archive);await finish(target,svc,id);for(const table of ['source_competitions','source_divisions','source_competition_memberships'])assert.equal(target.sqlite.prepare(`SELECT COUNT(*) n FROM ${table}`).get().n,1);assert.equal(target.sqlite.prepare('SELECT COUNT(*) n FROM source_events').get().n,0);}finally{source.close();target.close();}});

import {readSourceArchive,createDataFileController} from '../web/app/data-files.js';
test('the resumable ZIP is complete, reopens from the bounded job list and expires explicitly',async()=>{const f=fixture();try{const root=f.source();f.team('team',root);await f.event('old',root,'2024-08-04');await f.event('new',root,'2026-08-04');let svc=service(f);const started=await svc.create({team_id:'team',team_season_id:'ignored-season'});assert.equal(started.scope_kind,'connected_history');assert.equal(started.team_season_id,null);assert.equal(started.retention_hours,24);let result;for(let n=0;n<100;n++){result=await svc.capture(await svc.exportRow(started.id));f.commit(result);if(result.complete)break;if(n===1)svc=service(f);}assert.equal(result.complete,true);const listed=await svc.list({team_id:'team'});assert.equal(listed.items[0].state,'ready');const file=await (await svc.download(started.id)).blob(),archive=await readSourceArchive(file);assert.equal(archive.manifest.scope.scope_kind,'connected_history');const rows=[];for(const segment of archive.manifest.segments)rows.push(...(await archive.segment(segment)).rows);assert.ok(rows.some(r=>r.native_id==='old'));assert.ok(rows.some(r=>r.native_id==='new'));assert.equal(f.sqlite.prepare('SELECT COUNT(*) n FROM source_events').get().n,2);const expired=new DataFileService(f.db,{now:()=>Date.parse(AT)+86400001});await assert.rejects(()=>expired.exportStatus(started.id),e=>e.code==='data_file_expired');}finally{f.close();}});
test('disconnected saved private scopes can export and restore while creating no account or provider entitlement',async()=>{const source=fixture(),target=fixture();try{source.insert('provider_accounts',{id:'old-account',provider:'teamsnap',native_id:'known',name:'Saved owner'});const root=source.source('team','teamsnap','old-account');source.team('original',root,{account:'old-account'});await source.event('saved',root,'2024-08-04',{provider:'teamsnap',accountId:'old-account',generation:1});source.sqlite.prepare("UPDATE provider_accounts SET active=0,generation=generation+1 WHERE id='old-account'").run();const archive=await source.archive('original');target.insert('provider_accounts',{id:'target-account',provider:'teamsnap',native_id:'known',name:'Saved owner',active:0,generation:8});const tr=target.source('team','teamsnap','target-account');target.team('target',tr,{account:'target-account'});const {svc,id}=await stage(target,archive);await finish(target,svc,id);assert.equal(target.sqlite.prepare('SELECT COUNT(*) n FROM source_events').get().n,1);assert.equal(target.sqlite.prepare('SELECT active FROM provider_accounts').get().active,0);assert.equal(target.sqlite.prepare('SELECT generation FROM provider_accounts').get().generation,8);await reconcile(target);assert.equal(target.sqlite.prepare('SELECT COUNT(*) n FROM team_events WHERE app_team_id=?').get('target').n,1,'disconnected saved observations remain locally usable');assert.equal(target.sqlite.prepare('SELECT COUNT(*) n FROM account_source_teams').get().n,0);assert.equal(target.sqlite.prepare('SELECT COUNT(*) n FROM sync_jobs').get().n,0);}finally{source.close();target.close();}});
test('provider observations and owner corrections survive imported observations and interruption replay',async()=>{const source=fixture(),target=fixture();try{const root=source.source();source.team('original',root);await source.event('same',root,'2024-08-04',{home_score:1,away_score:2});await source.event('missing',root,'2025-08-04');const archive=await source.archive('original');const tr=target.source();target.team('target',tr);await target.event('same',tr,'2024-08-04',{home_score:9,away_score:0});const canonical=target.sqlite.prepare("SELECT event_id FROM event_source_links WHERE source_event_id='gotsport/public/same'").get().event_id;target.insert('domain_overrides',{app_team_id:'target',kind:'event',entity_id:canonical,fields:'{"title":"Owner correction"}',revision:4});const {svc,id}=await stage(target,archive);let completed=false;for(let n=0;n<100;n++){const restarted=service(target),page=await restarted.apply(id);if(n===0){const retry=await restarted.apply(id);assert.deepEqual(retry.statements,page.statements);}target.commit(page);if(page.complete){completed=true;break;}}assert.equal(completed,true);assert.equal(target.sqlite.prepare("SELECT home_score FROM source_events WHERE native_id='same'").get().home_score,9);assert.equal(target.sqlite.prepare('SELECT fields FROM domain_overrides').get().fields,'{"title":"Owner correction"}');assert.equal(target.sqlite.prepare('SELECT COUNT(*) n FROM source_events').get().n,2);assert.equal((await svc.apply(id)).complete,true);}finally{source.close();target.close();}});
