test('root generation changes fence every imported page after validation',async()=>{const source=fixture(),target=fixture();try{const root=source.source();source.team('original',root);await source.event('event',root,'2024-08-04');const archive=await source.archive('original'),tr=target.source();target.team('target',tr);const {svc,id}=await stage(target,archive);while(['queued','validating'].includes((await svc.importStatus(id)).state))target.commit(await svc.apply(id));target.sqlite.prepare("UPDATE team_source_connections SET generation=generation+1 WHERE id='root-target'").run();await assert.rejects(()=>svc.apply(id),e=>e.code==='data_authorization_changed');assert.equal(target.sqlite.prepare('SELECT COUNT(*) n FROM source_events').get().n,0);}finally{source.close();target.close();}});
test('late bad checksum and unapproved roots leave all source rows untouched',async()=>{const source=fixture(),target=fixture();try{const root=source.source();source.team('original',root);await source.event('event',root,'2024-08-04');const archive=await source.archive('original'),manifest=await manifestFor(archive),other=target.source('different');target.team('target',other);const svc=service(target);await assert.rejects(()=>svc.startImport({team_id:'target',manifest}),e=>e.code==='data_scope_invalid');const matching=target.source();target.sqlite.prepare("UPDATE team_source_connections SET source_team_id=? WHERE id='root-target'").run(matching);const started=await svc.startImport({team_id:'target',manifest});await svc.uploadSegment(started.id,0,archive.segments[0]);const bad=structuredClone(archive.segments[1]);bad.rows[0].title='Changed bytes';await assert.rejects(()=>svc.uploadSegment(started.id,1,bad),e=>e.code==='data_checksum_invalid');assert.equal(target.sqlite.prepare('SELECT COUNT(*) n FROM source_events').get().n,0);assert.equal((await svc.importStatus(started.id)).state,'staging');}finally{source.close();target.close();}});
test('snapshot clocks and derived membership changes invalidate captures, without widening import authorization',async()=>{const f=fixture();try{f.insert('provider_accounts',{id:'snapshot-account',provider:'teamsnap',native_id:'snapshot-owner',name:'Owner'});const root=f.source('team','teamsnap','snapshot-account');f.team('team',root,{account:'snapshot-account'});const season=f.season('team',2024),player=sourceKey('teamsnap','player','snapshot-account');f.insert('source_players',{id:player,provider:'teamsnap',scope:'snapshot-account',account_id:'snapshot-account',native_id:'player',name:'Player',evidence:'{}',content_hash:'player',observed_at:AT});f.insert('team_connection_seasons',{connection_id:'root-team',team_season_id:season,basis:'imported_snapshot'});f.insert('connection_roster_evidence',{connection_id:'root-team',team_season_id:season,source_player_id:player,basis_key:'snapshot',basis:'imported_snapshot',certainty:'preserved_uncertain',name:'Old name',jersey:'3',observed_at:AT,source_hash:'unchanged'});const q=datasetRevisionQuery('team',null),signature=()=>f.db.prepare(q.sql).bind(...q.params).first('signature'),first=await signature();f.sqlite.prepare("UPDATE connection_roster_evidence SET name='Different name' WHERE basis_key='snapshot'").run();const second=await signature();assert.notEqual(first,second);f.sqlite.prepare("UPDATE team_connection_seasons SET active=0 WHERE connection_id='root-team'").run();assert.notEqual(await signature(),second);}finally{f.close();}});

import {BudgetDB} from '../src/sync/budget.js';
test('maximum root scope admission and20-job reopening remain bounded per request',async()=>{const f=fixture();try{const first=f.source('1');f.team('target',first);for(let i=2;i<=32;i++){const source=f.source(String(i));f.insert('team_source_connections',{id:'extra-'+i,app_team_id:'target',source_team_id:source,scope_mode:'observed_history',created_at:AT});}const external={scope_kind:'connected_history',source_teams:Array.from({length:32},(_,i)=>({provider:'gotsport',native_id:String(i+1),account_ref:null})),accounts:[]},budget=new BudgetDB(f.db,48);const scope=await validateDatasetImportScope(new DomainRepository(budget),{teamId:'target'},external);assert.equal(scope.sourceTeams.length,32);assert.ok(budget.used<=8,'scope admission batches all roots/accounts');for(let i=0;i<21;i++)f.insert('data_file_imports',{id:crypto.randomUUID(),app_team_id:'target',team_season_id:null,scope_kind:'connected_history',manifest:'{"segments":[]}',state:'ready',created_at:Date.parse(AT),expires_at:Date.parse(AT)+86400000});const listBudget=new BudgetDB(f.db,48),svc=new DataFileService(listBudget,{now:()=>Date.parse(AT)}),page=await svc.list({team_id:'target',type:'imports',limit:20});assert.equal(page.items.length,20);assert.ok(listBudget.used<=3,'listing does not spend requests per job');const next=await svc.list({team_id:'target',type:'imports',limit:20,before:page.next_before,before_id:page.next_before_id});assert.equal(next.items.length,1);assert.equal(new Set([...page.items,...next.items].map(i=>i.id)).size,21,'same-millisecond jobs paginate without loss');}finally{f.close();}});

async function reconcile(f,team='target'){
 for(let pass=0;pass<5;pass++){
  for(const root of f.sqlite.prepare('SELECT * FROM team_source_connections WHERE app_team_id=? AND active=1').all(team)){let checkpoint={},complete=false;for(let page=0;page<150;page++){const next=await buildConnectionPage(f.db,{connectionId:root.id,teamId:team,generation:root.generation,checkpoint});f.commit(next);checkpoint=next.checkpoint;if(next.complete){complete=true;break;}}assert.equal(complete,true,'connection pages finish');}
  for(const season of f.sqlite.prepare('SELECT id FROM team_seasons WHERE app_team_id=?').all(team)){let checkpoint={},complete=false;for(let page=0;page<150;page++){const next=await buildProjectionPage(f.repo,team,season.id,checkpoint);f.commit(next);checkpoint=next.checkpoint;if(next.complete){complete=true;break;}}assert.equal(complete,true,'projection pages finish');}
  if(!f.sqlite.prepare('SELECT id FROM team_source_connections WHERE app_team_id=? AND active=1 AND input_revision>reconciled_revision').get(team))return;
 }
 assert.fail('Reconciliation did not converge.');
}
async function snapshotArchive(f,{event=false}={}){
 f.insert('provider_accounts',{id:'origin-account',provider:'teamsnap',native_id:'snapshot-owner',name:'Owner'});const root=f.source('team','teamsnap','origin-account');f.team('original',root,{account:'origin-account'});const season=f.season('original',2024),player=sourceKey('teamsnap','player','origin-account');f.insert('source_players',{id:player,provider:'teamsnap',scope:'origin-account',account_id:'origin-account',native_id:'player',name:'Current name',jersey:'22',evidence:'{}',content_hash:'current',observed_at:AT});let sourceEvent=null;if(event){await f.event('snapshot-game',root,'2024-08-02',{provider:'teamsnap',accountId:'origin-account',generation:1});sourceEvent=sourceKey('teamsnap','snapshot-game','origin-account');}f.insert('team_connection_seasons',{connection_id:'root-original',team_season_id:season,basis:'events'});f.insert('connection_roster_evidence',{connection_id:'root-original',team_season_id:season,source_player_id:player,basis_key:'historical',basis:'accepted_projection',certainty:'preserved_uncertain',source_event_id:sourceEvent,name:'Historical name',jersey:'8',observed_at:AT,source_hash:'original-history'});return f.archive('original');
}
