test('high-part-count downloads finish within the route statement budget',async()=>{const f=fixture();try{const root=f.source();f.team('target',root);const id=crypto.randomUUID(),parts=5200;f.insert('data_file_exports',{id,app_team_id:'target',team_season_id:null,scope_kind:'connected_history',kind:'dataset',scope:'{}',sections:'{}',source_revision:0,capture_signature:'saved',state:'ready',part_count:parts,byte_length:parts,created_at:Date.parse(AT),expires_at:Date.parse(AT)+86400000});const insert=f.sqlite.prepare('INSERT INTO data_file_parts(export_id,ordinal,bytes) VALUES(?,?,?)');for(let i=0;i<parts;i++)insert.run(id,i,Uint8Array.of(i%251));const budget=new BudgetDB(f.db,48),svc=new DataFileService(budget,{now:()=>Date.parse(AT)});budget.reserve(10);const response=await svc.download(id),data=new Uint8Array(await response.arrayBuffer());assert.equal(data.length,parts);assert.equal(data[5199],5199%251);assert.ok(budget.used<=32,'allow ten request setup/auth statements as well as every streaming read');}finally{f.close();}});
test('near64MiB downloads with maximal tiny-part overhead bound both every read and total statements',async()=>{const f=fixture();try{const root=f.source();f.team('target',root);const id=crypto.randomUUID(),small=4180,large=Math.floor((64*1024*1024-small)/64000),parts=small+large,total=small+large*64000;f.insert('data_file_exports',{id,app_team_id:'target',team_season_id:null,scope_kind:'connected_history',kind:'dataset',scope:'{}',sections:'{}',source_revision:0,capture_signature:'saved',state:'ready',part_count:parts,byte_length:total,created_at:Date.parse(AT),expires_at:Date.parse(AT)+86400000});const insert=f.sqlite.prepare('INSERT INTO data_file_parts(export_id,ordinal,bytes) VALUES(?,?,?)');f.sqlite.exec('BEGIN');for(let i=0;i<parts;i++)insert.run(id,i,new Uint8Array(i<small?1:64000));f.sqlite.exec('COMMIT');const budget=new BudgetDB(f.db,48),sizes=[];budget.measure=result=>{const binary=(result.results||[]).filter(row=>row.bytes);if(binary.length){const size=binary.reduce((n,row)=>n+row.bytes.byteLength,0);sizes.push(size);assert.ok(size<=4*1024*1024);assert.ok(binary.length<=256);}};budget.reserve(10);const response=await new DataFileService(budget,{now:()=>Date.parse(AT)}).download(id),reader=response.body.getReader();let downloaded=0;while(true){const {value,done}=await reader.read();if(done)break;downloaded+=value.byteLength;}assert.equal(downloaded,total);assert.ok(budget.used<=48);assert.ok(sizes.length<=35,JSON.stringify({reads:sizes.length,statements:budget.used}));}finally{f.close();}});

